import { Text, TouchableOpacity } from 'react-native'
import { colors, useTheme } from '@/theme'

type BadgeProps = {
	children: React.ReactNode
	color:
		| 'gray'
		| 'red'
		| 'orange'
		| 'yellow'
		| 'green'
		| 'teal'
		| 'blue'
		| 'purple'
		| 'black'
	icon?: React.ReactNode
	onPress?: () => void
	disabled?: boolean
}

export const Badge = ({
	children,
	color,
	icon,
	onPress,
	disabled = false
}: BadgeProps) => {
	const { theme } = useTheme()

	const colorKey = color === 'black' ? 'gray' : color
	const isBlack = color === 'black'

	const backgroundColor = colors[theme][colorKey][isBlack ? 600 : 25]
	const textColor = colors[theme][colorKey][isBlack ? 25 : 600]

	return (
		<TouchableOpacity
			disabled={disabled}
			onPress={onPress}
			style={{
				backgroundColor,
				borderRadius: 8,
				paddingVertical: 4,
				paddingHorizontal: 10,
				flexDirection: 'row',
				alignItems: 'center',
				gap: icon ? 6 : 0
			}}
		>
			{icon}
			<Text style={{ color: textColor, fontWeight: '500' }}>{children}</Text>
		</TouchableOpacity>
	)
}
